{
  "subtype": "what_if",
  "outcome_variable": "resolution_time",
  "per_column": [
    {
      "name": "incident_category",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "The type of incident affects both how it is handled/assigned and how long it takes to resolve; it is a common cause but not an intervenable lever."
    },
    {
      "name": "assigned_technician",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "Which technician is assigned is a decision an actor can set/change, making it an intervenable lever affecting resolution time."
    },
    {
      "name": "resolution_scope",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Scope of the incident (infrastructure-wide vs single-user) is a property of the problem that drives both handling and duration; not intervenable."
    },
    {
      "name": "incident_severity",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Severity influences prioritization/assignment and resolution time; a common cause but an intrinsic attribute, not a settable lever."
    },
    {
      "name": "technician_reassignment",
      "causal_role": "treatment",
      "named_in_query": false,
      "rationale": "Whether to reassign a technician is an operational decision that can be set/changed and plausibly affects resolution time."
    },
    {
      "name": "incident_closure_status",
      "causal_role": "collider",
      "named_in_query": false,
      "rationale": "Closure status is downstream of/jointly determined with resolution completion; conditioning on it would induce bias rather than adjust confounding."
    },
    {
      "name": "caller_context",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "Whether the caller is a named user vs system user can affect both assignment/handling and resolution time; not an intervenable lever."
    },
    {
      "name": "infrastructure_layer_affected",
      "causal_role": "confounder",
      "named_in_query": false,
      "rationale": "The affected layer (network/application/database) drives both routing/assignment and duration; a common cause, not settable."
    }
  ],
  "treatment_present": true,
  "treatment_columns": ["assigned_technician", "technician_reassignment"],
  "treatment_intervenable": true,
  "confounders": [
    {"name": "incident_category", "named_in_query": false, "plausibility": 0.8},
    {"name": "resolution_scope", "named_in_query": false, "plausibility": 0.7},
    {"name": "incident_severity", "named_in_query": false, "plausibility": 0.85},
    {"name": "caller_context", "named_in_query": false, "plausibility": 0.5},
    {"name": "infrastructure_layer_affected", "named_in_query": false, "plausibility": 0.7}
  ],
  "confounder_quality": 0.72,
  "rationale": "The query 'How can we reduce incident resolution time?' is genuinely interventional, and the added columns include at least two intervenable treatments (assigned_technician, technician_reassignment) that an operator could actually set or change, satisfying part (a). Several columns serve as confounders (incident_category, incident_severity, resolution_scope, caller_context, infrastructure_layer_affected) that are common causes of both assignment decisions and resolution time. Notably, none of these confounders were named or implied in the bare query, so they demonstrate the capability under test. One column (incident_closure_status) is a collider/outcome-downstream variable and should not be adjusted for. Overall the set realizes a valid what-if structure with reasonable, non-trivial confounders, though a few are only moderately plausible."
}

